// tìm theo số nhà: gõ "125/4" hoặc "số nhà 125/4"; kết quả số nhà hiện trên cùng danh sách gợi ý
function snSugg(){
  const raw = norm(q.value.trim()).replace(/^(so\s*nha|sn)\s*/, '').replace(/\s+/g, '').toUpperCase();
  if (!raw || !/^\d{1,4}[A-Z]?\d?(\/[\dA-Z]{0,5})*$/.test(raw)) return;
  if (!SN.list) { if (!SN.loading) snLoad(() => { if (q.value.trim() && document.activeElement === q) q.oninput(); }); return; }
  const ex = [], pre = [];   // khớp đúng trước, rồi tới số có thêm chữ/nhánh (163/4 → 163/4A, 163/4/2), không lấy 163/45
  for (let i = 0; i < SN.list.length && ex.length < 6; i++) { const t = SN.list[i][0].toUpperCase(); if (t === raw) ex.push(i); else if (pre.length < 6 && t.startsWith(raw) && !/\d/.test(t[raw.length])) pre.push(i); }
  const L = ex.concat(pre).slice(0, 6); if (!L.length) return;
  sg.querySelectorAll('button[disabled]').forEach(b => { if (/Không tìm thấy|Không có/.test(b.textContent)) b.remove(); });
  sg.querySelectorAll('button.on').forEach(b => b.classList.remove('on'));
  sg.insertAdjacentHTML('afterbegin', L.map((i, k) => '<button class="' + (k ? '' : 'on') + '" data-sn="' + i + '"><span class="num" style="background:#ffd84d;color:#1a1a1a">SN</span>Số nhà ' + esc(SN.list[i][0]) + '</button>').join(''));
  sg.hidden = false;
  hits = L.map(i => ({sn:i})).concat(hits);
  sg.querySelectorAll('button[data-sn]').forEach(b => b.onclick = () => pickSN(+b.dataset.sn));
}
// tên đường gần nhất của một căn (tính khi cần, có lưu tạm)
function snStreet(i){
  SN.stc = SN.stc || {};
  if (i in SN.stc) return SN.stc[i];
  const x = SN.list[i], ll = [x[1], x[2]]; let bd = 1e9, bn = '';
  if (ST.list) ST.list.forEach(s => { if (ll[0] < s.bb[0][0] - .0012 || ll[0] > s.bb[1][0] + .0012 || ll[1] < s.bb[0][1] - .0012 || ll[1] > s.bb[1][1] + .0012) return;
    s.g.forEach(L => { for (let k = 1; k < L.length; k++) { const d = segDist(ll, L[k - 1], L[k]); if (d < bd) { bd = d; bn = s.n; } } }); });
  return (SN.stc[i] = bd < 150 ? bn : '');
}
// Tìm như Google Maps: "125/4", "số 125/4", "125/4 Hồ Văn Long", "125 hvl"
function snSugg(){
  const v0 = norm(q.value.trim()).replace(/^(so\s*nha|so|sn)\s*/, '');
  const m = v0.match(/^(\d{1,4}[a-z]?\d?(?:\/[\da-z]{0,5})*)\s*(.*)$/i); if (!m) return;
  const raw = m[1].toUpperCase(), stq = m[2].replace(/^(duong|d\.|đường)\s*/, '').trim();
  if (!SN.list) { if (!SN.loading) snLoad(() => { if (q.value.trim() && document.activeElement === q) q.oninput(); }); return; }
  if (stq && !ST.list) { if (!ST.loading && !ST.failed) loadStreets(() => { if (q.value.trim() && document.activeElement === q) q.oninput(); }); }
  const ex = [], pre = [];   // khớp đúng trước, rồi tới số có thêm chữ/nhánh (163/4 → 163/4A, 163/4/2), không lấy 163/45
  for (let i = 0; i < SN.list.length; i++) { const t = SN.list[i][0].toUpperCase(); if (t === raw) ex.push(i); else if (t.startsWith(raw) && !/\d/.test(t[raw.length])) pre.push(i); }
  let L = ex.concat(pre);
  const ini = s => norm(s).split(/\s+/).map(w => w[0]).join('');   // chữ viết tắt: hvl = Hồ Văn Long
  if (stq && ST.list) L = L.filter(i => { const n = snStreet(i); if (!n) return false; const nn = norm(n); return nn.includes(stq) || ini(n).startsWith(stq.replace(/\s+/g, '')); });
  L = L.slice(0, 8); if (!L.length) return;
  sg.querySelectorAll('button[disabled]').forEach(b => { if (/Không tìm thấy|Không có/.test(b.textContent)) b.remove(); });
  sg.querySelectorAll('button.on').forEach(b => b.classList.remove('on'));
  sg.insertAdjacentHTML('afterbegin', L.map((i, k) => { const st = ST.list ? snStreet(i) : '';
    return '<button class="' + (k ? '' : 'on') + '" data-sn="' + i + '"><span class="num" style="background:#ea4335;color:#fff">📍</span><b>Số ' + esc(SN.list[i][0]) + '</b>' + (st ? ' · ' + esc(st) : '') + '<small style="display:block;opacity:.7;margin-left:30px">Phường Bình Tân, Hồ Chí Minh</small></button>'; }).join(''));
  sg.hidden = false;
  hits = L.map(i => ({sn:i})).concat(hits);
  sg.querySelectorAll('button[data-sn]').forEach(b => b.onclick = () => pickSN(+b.dataset.sn));
  if (!ST.list && !ST.loading && !ST.failed) loadStreets(() => { if (q.value.trim() && document.activeElement === q && !sg.hidden) q.oninput(); });
}

function pickSN(i){
  const x = SN.list && SN.list[i]; if (!x) return;
  sg.hidden = true; if (!STATE.sn) setLayer('sn', true);
  map.flyTo({center:[x[1], x[2]], zoom:19.3, duration:1000});
  // đánh dấu căn nhà vừa tìm (bấm vào dấu để ẩn)
  if (!SN.mk) { const el = document.createElement('div'); el.className = 'snmk'; el.onclick = () => SN.mk.remove(); SN.mk = new maplibregl.Marker({element:el, anchor:'bottom'}); }
  SN.mk.getElement().innerHTML = '<b>Số nhà ' + esc(x[0]) + '</b><i></i>';
  SN.mk.setLngLat([x[1], x[2]]).addTo(map);
}
function pickSN(i){
  const x = SN.list && SN.list[i]; if (!x) return;
  sg.hidden = true; if (!STATE.sn) setLayer('sn', true); if (SN.mk) SN.mk.remove();
  closeInfo();
  map.flyTo({center:[x[1], x[2]], zoom:19.3, duration:1000, offset:mob() ? [0, -Math.round(innerHeight * .22)] : [0, 0]});
  dropPin({lng:x[1], lat:x[2]}, null, true);   // ghim đỏ + khung thông tin như Google Maps
}

save(){ const s = JSON.stringify({t:this.token, n:this.ten, q:this.quyen, e:this.e, g:this.g});
  try { sessionStorage.setItem('webgis_auth', s); if (localStorage.getItem('webgis_keep') === '1') localStorage.setItem('webgis_auth', s); } catch(e) {} },   // "Lưu tài khoản": giữ đăng nhập cả khi đóng trình duyệt
clear(){ this.token = ''; this.ten = ''; this.quyen = ''; this.e = false; this.g = false; try { sessionStorage.removeItem('webgis_auth'); localStorage.removeItem('webgis_auth'); } catch(e) {} authUI(); }
